def step(observation):
    memory = observation.get('memory') or {}
    prev = observation.get('previous')
    action = memory.get('action', 4)

    if prev is not None:
        fb = prev.get('feedback', {})
        errors = fb.get('server_errors', 0)
        durations = sorted(fb.get('dispatch_seconds', []))
        p90 = durations[min(len(durations) - 1, int(0.9 * len(durations)))] if durations else 0.0

        # If server errors occur, DB pool is saturated (capacity 2 limit)
        if errors > 0:
            action = 2
        elif p90 > 0.08:
            # High latency under higher concurrency suggests queue backup
            if action > 4:
                action = 4
            elif action == 4 and errors > 0:
                action = 2
        else:
            # Healthy and error-free: if action 2 or 4 was clean, attempt 4 or 8
            if action < 4:
                action = 4
            elif action == 4 and errors == 0 and p90 < 0.06:
                action = 8
            elif action >= 8:
                action = 8
    else:
        # Start conservatively at 4, which performs robustly on both regimes
        action = 4

    memory['action'] = action
    return {'action': action, 'memory': memory}

